// Extract Grain recording link from message
const items = $input.all();
const results = [];

for (const item of items) {
  const text = item.json.text || '';
  const ts = item.json.ts || '';

  let grainLink = '';

  // Try Slack-formatted URL: <https://grain.com/...|optional text>
  const slackUrlMatch = text.match(/<(https?:\/\/[^|>]*grain\.[^|>]*)(?:\|[^>]*)?>/);
  if (slackUrlMatch) {
    grainLink = slackUrlMatch[1];
  }

  // Try plain URL
  if (!grainLink) {
    const plainUrlMatch = text.match(/(https?:\/\/[^\s]*grain\.[^\s]*)/);
    if (plainUrlMatch) {
      grainLink = plainUrlMatch[1];
    }
  }

  // Check attachments
  if (!grainLink && item.json.attachments) {
    for (const att of item.json.attachments) {
      const url = att.original_url || att.title_link || att.from_url || '';
      if (url.includes('grain')) {
        grainLink = url;
        break;
      }
    }
  }

  if (grainLink) {
    results.push({
      json: {
        grainLink,
        messageId: ts.replace('.', '_')
      }
    });
  }
}

return results.length > 0 ? results : [];

// Prevent duplicate posts using workflow static data
const items = $input.all();
const results = [];

const staticData = $getWorkflowStaticData('global');
const posted = staticData.postedMessages || [];

for (const item of items) {
  const id = item.json.messageId;
  if (!posted.includes(id)) {
    posted.push(id);
    results.push(item);
  }
}

// Keep only last 50 IDs
staticData.postedMessages = posted.slice(-50);

return results;
